import React, { useState, useEffect } from 'react';

interface GameImageProps {
    src: string;
    alt: string;
    className?: string; 
    imgClassName?: string;
    priority?: boolean; // Si es true, carga la imagen HD con alta prioridad
    style?: React.CSSProperties;
}

// Función inteligente para obtener el thumbnail de Imgur
const getLowResUrl = (url: string) => {
    if (!url.includes('imgur.com')) return url;
    // Insertamos 'l' (Large Thumbnail - 640px) antes de la extensión
    // Esto reduce una imagen de 4MB a ~40KB para la carga inicial
    return url.replace(/(\.[^.]*)$/, 'l$1');
};

export const GameImage: React.FC<GameImageProps> = ({ 
    src, 
    alt, 
    className = "", 
    imgClassName = "",
    priority = false, 
    style = {} 
}) => {
    const [isHdLoaded, setIsHdLoaded] = useState(false);
    const lowResSrc = getLowResUrl(src);

    return (
        <div className={`relative overflow-hidden ${className}`} style={style}>

            {/* 1. LAYER LOW-RES (Instantáneo) */}
            {/* Se muestra inmediatamente. Filtro blur para ocultar la compresión. */}
            <img
                src={lowResSrc}
                alt=""
                aria-hidden="true"
                className={`
                    absolute inset-0 w-full h-full object-cover select-none
                    transition-opacity duration-1000 ease-in-out
                    filter blur-md scale-105
                    ${isHdLoaded ? 'opacity-0' : 'opacity-100'}
                    ${imgClassName}
                `}
            />

            {/* 2. LAYER HIGH-RES (Asíncrono) */}
            {/* Se carga en segundo plano. Cuando termina, hace fade-in sobre la low-res. */}
            <img
                src={src}
                alt={alt}
                draggable="false"
                loading={priority ? "eager" : "lazy"}
                fetchPriority={priority ? "high" : "low"}
                decoding="async"
                onLoad={() => setIsHdLoaded(true)}
                className={`
                    relative w-full h-full object-cover select-none
                    transition-opacity duration-700 ease-out
                    ${isHdLoaded ? 'opacity-100' : 'opacity-0'}
                    ${imgClassName} 
                `}
            />
        </div>
    );
};

