                    <h1 className="font-['Teko'] text-7xl md:text-8xl font-bold tracking-widest text-transparent bg-clip-text bg-gradient-to-b from-white to-gray-500">
                        UNIBELANDS
                    </h1>
                    <div className="flex justify-between w-full px-2">
                        <span className="font-['Roboto_Mono'] text-[10px] text-[#F2D019] tracking-[0.2em]">FAST.BOOT</span>
                        <span className="font-['Roboto_Mono'] text-[10px] text-[#00F0FF] tracking-[0.2em]">V3.0</span>
                    </div>
                </div>

                <div className="w-full h-14 flex items-center justify-center relative mt-4">
