import React, { useState } from 'react';

interface GameImageProps {
    src: string;
    alt: string;
    className?: string; 
    imgClassName?: string;
    priority?: boolean;
    style?: React.CSSProperties;
    forceLowRes?: boolean; // Nueva prop: Si es true, NUNCA carga la HD
}

// Helper para obtener URL ligera de Imgur
const getLowResUrl = (url: string, size: 'l' | 'm' = 'l') => {
    if (!url.includes('imgur.com')) return url;
    // Si ya tiene sufijo, no hacemos nada
    if (url.match(/[sbtmlh]\.(png|jpg|jpeg)/)) return url;
    return url.replace(/(\.[^.]*)$/, `${size}$1`);
};

export const GameImage: React.FC<GameImageProps> = ({ 
    src, 
    alt, 
    className = "", 
    imgClassName = "",
    priority = false, 
    style = {},
    forceLowRes = false
}) => {
    const [isHdLoaded, setIsHdLoaded] = useState(false);

    // Si forzamos low res, usamos 'm' (Medium 320px) o 'l' (Large 640px) dependiendo del caso
    // Para blur up normal usamos 'l'
    const lowResSrc = getLowResUrl(src, forceLowRes ? 'm' : 'l');

    // Si forceLowRes es true, el "High Res" es el lowResSrc.
    const finalSrc = forceLowRes ? lowResSrc : src;

    return (
        // FIX CRÍTICO: Eliminado 'overflow-hidden'. 
        // Esto permitía que el blur no se saliera, pero cortaba las estructuras que usaban scale().
        <div className={`relative ${className}`} style={style}>

            {/* 1. LAYER LOW-RES (Blur Base) */}
            {/* Solo se muestra si NO estamos forzando low res (ya que si forzamos, la imagen principal es la low res) */}
            {!forceLowRes && (
                <img
                    src={lowResSrc}
                    alt=""
                    aria-hidden="true"
                    className={`
                        absolute inset-0 w-full h-full object-cover select-none
                        transition-opacity duration-700 ease-in-out
                        ${isHdLoaded ? 'opacity-0' : 'opacity-100 blur-sm'}
                        ${imgClassName}
                    `}
                />
            )}

            {/* 2. LAYER FINAL (HD o LowRes forzada) */}
            <img
                src={finalSrc}
                alt={alt}
                draggable="false"
                loading={priority ? "eager" : "lazy"}
                fetchPriority={priority ? "high" : "low"}
                decoding="async"
                onLoad={() => setIsHdLoaded(true)}
                className={`
                    relative w-full h-full object-cover select-none
                    transition-opacity duration-500 ease-out
                    ${forceLowRes ? 'opacity-100 blur-[1px]' : (isHdLoaded ? 'opacity-100' : 'opacity-0')}
                    ${imgClassName} 
                `}
            />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// OPTIMIZACIÓN: Usamos sufijo 'l' (Large Thumbnail ~640px) o 'h' (Huge Thumbnail ~1024px) 
// en lugar de la imagen original (4K).
// Esto reduce el peso de 5MB por nube a ~50KB.
const CLOUD_URLS = [
    'https://i.imgur.com/JTrVDQ3l.png', 
    'https://i.imgur.com/58lHfHwl.png',
    'https://i.imgur.com/X8FIpPel.png', 
    'https://i.imgur.com/hcdTnXql.png',
    'https://i.imgur.com/C08w8E1l.png', 
    'https://i.imgur.com/Nypf6gXl.png',
    'https://i.imgur.com/jd76dmdl.png'
];

interface ThreeSkyProps {
    scrollRef: React.MutableRefObject<number>;
}

export const ThreeSky: React.FC<ThreeSkyProps> = React.memo(({ scrollRef }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        const aspect = w / h;

        const scene = new THREE.Scene();

        const frustumSize = 1000;
        const camera = new THREE.OrthographicCamera(
            frustumSize * aspect / -2,
            frustumSize * aspect / 2,
            frustumSize / 2,
            frustumSize / -2,
            1,
            2000
        );
        camera.position.z = 1000;

        let renderer: THREE.WebGLRenderer | undefined;

        try {
            renderer = new THREE.WebGLRenderer({ 
                alpha: true, 
                antialias: false,
                powerPreference: "low-power", // Pedimos a la GPU modo ahorro
                depth: false,
                stencil: false,
                preserveDrawingBuffer: false
            });
        } catch (error) {
            console.error("ThreeSky: Error creating WebGL context:", error);
            return;
        }

        if (!renderer) return;

        renderer.setSize(w, h);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5)); // Bajamos pixel ratio para rendimiento

        renderer.domElement.style.position = 'absolute';
        renderer.domElement.style.top = '0';
        renderer.domElement.style.left = '0';
        renderer.domElement.style.zIndex = '1';
        renderer.domElement.style.pointerEvents = 'none';

        containerRef.current.appendChild(renderer.domElement);

        const clouds: THREE.Mesh[] = [];
        const loader = new THREE.TextureLoader();
        const cloudGeo = new THREE.PlaneGeometry(350, 250);

        const getSceneWidth = () => 1000 * (containerRef.current?.clientWidth || 1000) / (containerRef.current?.clientHeight || 1000);

        const setupCloud = (sprite: THREE.Mesh, layerIndex: number) => {
            const sceneW = getSceneWidth();
            const rangeX = sceneW * 4.0; 
            sprite.position.x = (Math.random() * rangeX) - (rangeX / 2);
            const flip = Math.random() > 0.5 ? -1 : 1;
            sprite.rotation.z = (Math.random() * 0.1) - 0.05;

            sprite.userData = { speed: 0, parallax: 0, baseX: sprite.position.x };

            if (layerIndex === 0) { 
                sprite.position.z = -200;
                sprite.position.y = (Math.random() * 150) + 300; 
                const scale = 2.8 + Math.random() * 1.2; 
                sprite.scale.set(scale * flip, scale, 1);
                (sprite.material as THREE.MeshBasicMaterial).opacity = 0.35 + Math.random() * 0.15;
                sprite.userData.speed = 0.25;
                sprite.userData.parallax = 0.06;
            } else if (layerIndex === 1) {
                sprite.position.z = -50;
                sprite.position.y = (Math.random() * 150) + 200;
                const scale = 2.0 + Math.random() * 1.0;
                sprite.scale.set(scale * flip, scale, 1);
                (sprite.material as THREE.MeshBasicMaterial).opacity = 0.6 + Math.random() * 0.2;
                sprite.userData.speed = 0.5;
                sprite.userData.parallax = 0.18;
            } else {
                sprite.position.z = 100;
                sprite.position.y = (Math.random() * 200) + 150;
                const scale = 1.7 + Math.random() * 0.8;
                sprite.scale.set(scale * flip, scale, 1);
                (sprite.material as THREE.MeshBasicMaterial).opacity = 0.8 + Math.random() * 0.2;
                sprite.userData.speed = 0.8;
                sprite.userData.parallax = 0.35;
            }
        };

        // OPTIMIZACIÓN: Reducido de 28 a 14 nubes. Suficiente para ambientar sin saturar.
        const CLOUD_COUNT = 14; 
        for (let i = 0; i < CLOUD_COUNT; i++) {
            const url = CLOUD_URLS[i % CLOUD_URLS.length];
            loader.load(url, (texture) => {
                const material = new THREE.MeshBasicMaterial({
                    map: texture,
                    transparent: true,
                    depthWrite: false,
                });
                const sprite = new THREE.Mesh(cloudGeo, material);
                setupCloud(sprite, i % 3);
                scene.add(sprite);
                clouds.push(sprite);
            });
        }

        let animationId: number;
        const animate = () => {
            animationId = requestAnimationFrame(animate);
            if (document.hidden) return;
            if (!containerRef.current || !renderer) return;

            const currentW = containerRef.current.clientWidth;
            const currentH = containerRef.current.clientHeight || 1;
            const currentAspect = currentW / currentH;
            const sceneVisibleWidth = 1000 * currentAspect; 
            const pixelToUnitRatio = sceneVisibleWidth / (currentW || 1);
            const respawnLimit = sceneVisibleWidth * 2.5; 

            for (const cloud of clouds) {
                cloud.userData.baseX -= cloud.userData.speed;
                const parallaxEffect = (scrollRef.current - window.innerWidth) * pixelToUnitRatio * cloud.userData.parallax;
                const finalX = cloud.userData.baseX - parallaxEffect;

                if (finalX < -respawnLimit) {
                    cloud.userData.baseX += (respawnLimit * 2);
                }
                cloud.position.x = finalX;
            }

            renderer.render(scene, camera);
        };

        animate();

        const handleResize = () => {
            if (!containerRef.current || !renderer) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;
            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);

            if (containerRef.current && renderer?.domElement && containerRef.current.contains(renderer.domElement)) {
                containerRef.current.removeChild(renderer.domElement);
            }

            cloudGeo.dispose();
            clouds.forEach(cloud => {
                if (cloud.material instanceof THREE.Material) {
                    if (cloud.material instanceof THREE.MeshBasicMaterial && cloud.material.map) {
                        cloud.material.map.dispose();
                    }
                    cloud.material.dispose();
                }
            });

            if (renderer) {
                renderer.dispose();
                renderer.forceContextLoss();
            }
        };
    }, []);

    return (
        <div 
            id="cielo-container" 
            ref={containerRef}
            className="w-full h-full relative overflow-hidden" 
            style={{ 
                background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', 
                zIndex: 0 
            }}
        >
            <div 
                className="absolute inset-0 w-full h-full pointer-events-none"
                style={{
                    background: 'linear-gradient(to bottom, transparent 0%, rgba(200, 225, 255, 0) 50%, rgba(255, 255, 255, 0.5) 80%, #FFFFFF 100%)',
                    zIndex: 0
                }}
            />
        </div>
    );
});

import { useState, useEffect, useRef } from 'react';

export const DUST_CONFIG = {
    // OPTIMIZACIÓN: Sufijo 'l' para usar la versión ligera/borrosa automáticamente
    IMAGE_URL: "https://i.imgur.com/fzslzur.png".replace(/(\.[^.]*)$/, 'l$1'),
    CONSTRAINTS: {
        MAX_CONCURRENT: 2, // Reducido de 3 a 2 para menos carga de DOM
        OPACITY_MIN: 0.2,  
        OPACITY_MAX: 0.5,  
        SPAWN_CHECK_INTERVAL: 3000 // Intervalo más largo (menos checks)
    },
    ANIMATION: {
        SIZE_MIN: 30, 
        SIZE_MAX: 75, 
        DURATION_MIN: 25, 
        DURATION_MAX: 45, 
    }
};

export interface Particle {
    id: number;
    size: number;
    top: number;
    duration: number;
    zIndex: number;
    opacity: number;
    rotation: number;
    yOffset: number;
}

export const useDustSystem = () => {
    const [particles, setParticles] = useState<Particle[]>([]);
    const nextId = useRef(0);

    useEffect(() => {
        const random = (min: number, max: number) => Math.random() * (max - min) + min;

        const attemptSpawn = () => {
            setParticles(currentParticles => {
                if (currentParticles.length >= DUST_CONFIG.CONSTRAINTS.MAX_CONCURRENT) {
                    return currentParticles;
                }

                if (Math.random() > 0.45) {
                    return currentParticles; 
                }

                const id = nextId.current++;
                const size = random(DUST_CONFIG.ANIMATION.SIZE_MIN, DUST_CONFIG.ANIMATION.SIZE_MAX);
                const top = random(5, 75); 
                const duration = random(DUST_CONFIG.ANIMATION.DURATION_MIN, DUST_CONFIG.ANIMATION.DURATION_MAX);
                const zIndex = 30 + Math.floor(top / 10); 
                const opacity = random(DUST_CONFIG.CONSTRAINTS.OPACITY_MIN, DUST_CONFIG.CONSTRAINTS.OPACITY_MAX);
                const rotation = random(-45, 45); 
                const yOffset = random(-15, 15);  

                const newParticle: Particle = {
                    id,
                    size,
                    top,
                    duration,
                    zIndex,
                    opacity,
                    rotation,
                    yOffset
                };

                setTimeout(() => {
                    setParticles(prev => prev.filter(p => p.id !== id));
                }, duration * 1000);

                return [...currentParticles, newParticle];
            });
        };

        const intervalId = setInterval(attemptSpawn, DUST_CONFIG.CONSTRAINTS.SPAWN_CHECK_INTERVAL);

        return () => clearInterval(intervalId);
    }, []);

    return particles;
};
